package com.servicerca.model;
import jakarta.persistence.*;import lombok.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="report") @Getter @Setter @Builder @NoArgsConstructor @AllArgsConstructor public class Report { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="reporter_id") private User reporter; @ManyToOne(optional=false) @JoinColumn(name="reported_user_id") private User reportedUser; @ManyToOne @JoinColumn(name="request_id") private ServiceRequest request; @Column(nullable=false,length=60) private String reason; @Column(length=800) private String details; @Column(name="created_at",nullable=false) private Instant createdAt; @PrePersist void prePersist(){if(createdAt==null)createdAt=Instant.now();} }
